fn numpy_not_equal(x1: Vec<i8>, x2: Vec<i8>) -> Vec<bool> {
    // Since x1 and x2 have the same length, we can safely zip their iterators.
    x1.into_iter()
      .zip(x2.into_iter())
      .map(|(a, b)| a != b)
      .collect()
}

